package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.jobs.*;
import java.nio.file.*;import java.util.concurrent.*;import java.time.*;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
class ProviderMonitoringConfigurationTest {
 @TempDir Path directory;
 String[] flags(){return new String[]{"site.ops.provider.enabled=true","site.browser.enabled=true","site.collector.enabled=true","site.execution.worker.enabled=true"};}
 ApplicationContextRunner runner(Path scopes){var executor=mock(ScheduledExecutorService.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenReturn(mock(ScheduledFuture.class));return new ApplicationContextRunner().withUserConfiguration(ProviderMonitoringConfiguration.class).withBean(javax.sql.DataSource.class,()->mock(javax.sql.DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withBean("providerMonitoringExecutor",ScheduledExecutorService.class,()->executor).withPropertyValues(flags()).withPropertyValues("SITE_OPERATIONAL_SCOPES="+scopes);}
 String validScopes(){return OperationalScopeCatalogTest.scopes().replace(OperationalScopeCatalogTest.key("OPS-08","provider"),"{\"rule_id\":\"OPS-08\",\"component\":\"java\",\"resource_key\":\"deepseek-flash\"}");}
 @Test void missingAnyFlagCreatesNoThreadOrFactProvider(){for(int disabled=0;disabled<4;disabled++){var values=flags();values[disabled]=values[disabled].replace("true","false");new ApplicationContextRunner().withUserConfiguration(ProviderMonitoringConfiguration.class).withPropertyValues(values).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(ProviderMonitoringCycle.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());});}}
 @Test void actualAssemblyBindsBothNativeProvidersWithoutReadingEitherOrSql()throws Exception{var file=directory.resolve("scopes.json");Files.writeString(file,validScopes());runner(file).run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(ProviderMonitoringCycle.class).size());assertTrue(c.getBean(ProviderMonitoringConfiguration.Loop.class).isRunning());verifyNoInteractions(c.getBean(javax.sql.DataSource.class));var cycle=c.getBean(ProviderMonitoringCycle.class);try{var account=ProviderMonitoringCycle.class.getDeclaredField("account");account.setAccessible(true);assertInstanceOf(com.lianxibu.site.repository.jobs.DeepSeekReadinessClient.class,account.get(cycle));var calls=ProviderMonitoringCycle.class.getDeclaredField("calls");calls.setAccessible(true);assertInstanceOf(com.lianxibu.site.repository.jobs.JdbcProviderCallTelemetry.class,calls.get(cycle));}catch(ReflectiveOperationException e){throw new AssertionError(e);}});}
 @Test void wrongComponentResourceOrMissingDatasourceFailsClosed()throws Exception{var file=directory.resolve("scopes.json");for(String text:new String[]{OperationalScopeCatalogTest.scopes(),validScopes().replace("deepseek-flash","fictional-other-provider"),validScopes().replace("\"component\":\"java\",\"resource_key\":\"deepseek-flash\"","\"component\":\"other\",\"resource_key\":\"deepseek-flash\"")}){Files.writeString(file,text);runner(file).run(c->assertNotNull(c.getStartupFailure()));}Files.writeString(file,validScopes());new ApplicationContextRunner().withUserConfiguration(ProviderMonitoringConfiguration.class).withPropertyValues(flags()).withPropertyValues("SITE_OPERATIONAL_SCOPES="+file).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).run(c->assertNotNull(c.getStartupFailure()));}
    @Test void loopRunsOnItsExecutorKeepsRetryingAndCancelsOnStop() {
        var executor=mock(ScheduledExecutorService.class);var cycle=mock(ProviderMonitoringCycle.class);var tick=new AtomicReference<Runnable>();var future=mock(ScheduledFuture.class);
        when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));assertEquals(TimeUnit.SECONDS.toNanos(60),(long)a.getArgument(2));return future;});
        when(cycle.tick()).thenThrow(new IllegalStateException("fictional failure")).thenReturn(ProviderMonitoringCycle.Outcome.SAMPLED);
        var loop=new ProviderMonitoringConfiguration.Loop(cycle,executor,Clock.fixed(Instant.parse("2026-10-01T00:00:10Z"),ZoneOffset.UTC));loop.start();verify(cycle).start();verify(cycle,never()).tick();tick.get().run();assertTrue(loop.hasFailure());tick.get().run();assertFalse(loop.hasFailure());loop.stop();tick.get().run();verify(cycle,times(2)).tick();verify(cycle).stop();verify(future).cancel(true);assertFalse(loop.isRunning());
    }
    @Test void shutdownCallbackWaitsForInFlightAndSchedulerFailureDoesNotPretendRunning()throws Exception {
        var executor=mock(ScheduledExecutorService.class);var cycle=mock(ProviderMonitoringCycle.class);var tick=new AtomicReference<Runnable>();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var done=new CountDownLatch(1);
        when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return mock(ScheduledFuture.class);});
        when(cycle.tick()).thenAnswer(a->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return ProviderMonitoringCycle.Outcome.STOPPED;});
        var loop=new ProviderMonitoringConfiguration.Loop(cycle,executor,Clock.systemUTC());var runner=Executors.newSingleThreadExecutor();try{loop.start();runner.submit(()->tick.get().run());assertTrue(entered.await(1,TimeUnit.SECONDS));loop.stop(done::countDown);assertEquals(1,done.getCount());assertThrows(IllegalStateException.class,loop::start);release.countDown();assertTrue(done.await(1,TimeUnit.SECONDS));}finally{release.countDown();runner.shutdownNow();}
        when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenThrow(new RejectedExecutionException());assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());
    }
}
